package com.certmanage;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import com.certmanage.certificate.*;
import com.certmanage.notification.NotificationService;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:integration;DB_CLOSE_DELAY=-1","app.encryption-key-file=target/test-master.key"})
class NotificationTest {
 @Autowired com.certmanage.common.ExecutionLog logs;@Autowired JdbcTemplate db;@Autowired NotificationService notifications;@Autowired CertificateService certs;@Autowired TransactionTemplate tx;
 @Test void successfulDeliveryIsNotSentAgain(){tx.execute(s->{long id=((Number)certs.issue(Map.of("kind","ROOT","cn","Success Notify Root","days",3650),"admin").get("id")).longValue();db.update("insert into notification_deliveries(asset_id,policy_id,threshold_days,recipient_address,recipient_key,not_after_snapshot,cn_snapshot,purpose_snapshot,message_id) values(?,1,30,'notify@example.test','notify@example.test',dateadd('DAY',29,current_timestamp),'Success Notify Root','GENERAL','<stable@example.test>')",id);var transport=org.mockito.Mockito.mock(com.certmanage.smtp.SmtpService.class);var unstableLog=org.mockito.Mockito.spy(logs);org.mockito.Mockito.doThrow(new org.springframework.dao.DataAccessResourceFailureException("audit unavailable")).doCallRealMethod().when(unstableLog).append(org.mockito.ArgumentMatchers.eq("NOTIFICATION"),org.mockito.ArgumentMatchers.eq("DELIVERY_SUCCESS"),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.isNull(),org.mockito.ArgumentMatchers.isNull(),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyLong(),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyMap());var worker=new NotificationService(db,transport,unstableLog);worker.sendPending();worker.sendPending();var body=org.mockito.ArgumentCaptor.forClass(String.class);org.mockito.Mockito.verify(transport).send(org.mockito.ArgumentMatchers.eq("notify@example.test"),org.mockito.ArgumentMatchers.anyString(),body.capture(),org.mockito.ArgumentMatchers.eq("<stable@example.test>"));assertTrue(body.getValue().contains("归属：自有证书"));assertTrue(body.getValue().contains("剩余天数：29"));assertEquals("SENT",db.queryForObject("select delivery_status from notification_deliveries where asset_id=?",String.class,id));assertEquals(1,db.queryForObject("select count(*) from notification_attempts where delivery_id in(select id from notification_deliveries where asset_id=?) and outcome='SUCCESS'",Integer.class,id));s.setRollbackOnly();return null;});}
 @Test void scansExactlyOnceAndFailedSmtpIsNotSuccess(){tx.execute(s->{long id=((Number)certs.issue(Map.of("kind","ROOT","cn","Notify Root","days",3650),"admin").get("id")).longValue();db.update("update notification_policy set enabled=true,include_ca=true,scan_time='00:00:00',timezone_id='UTC' where id=1");db.update("delete from notification_thresholds");db.update("insert into notification_thresholds values(1,3650)");db.update("delete from notification_recipients");db.update("insert into notification_recipients(policy_id,email_address,email_key) values(1,'notify@example.test','notify@example.test')");notifications.scan();notifications.scan();assertEquals(1,db.queryForObject("select count(*) from notification_deliveries where asset_id=?",Integer.class,id));db.update("delete from smtp_config");notifications.sendPending();assertEquals("RETRY_WAIT",db.queryForObject("select delivery_status from notification_deliveries where asset_id=?",String.class,id));assertEquals(0,db.queryForObject("select count(*) from notification_deliveries where asset_id=? and sent_at is not null",Integer.class,id));s.setRollbackOnly();return null;});}
}
